// Regrouper le scénario de retour d'une fiche produit vers le catalogue.
describe('Swag Labs product catalogue', () => {
  // Se connecter avant le scénario avec la commande partagée.
  beforeEach(() => {
    // Ouvrir une session utilisateur standard.
    cy.login();
  });

  // Fermer la session après le scénario avec la commande partagée.
  afterEach(() => {
    // Déconnecter l'utilisateur après la vérification.
    cy.logout();
  });

  // Définir le scénario de retour à la liste depuis une fiche produit.
  it('retourne à la liste des produits depuis le détail', () => {
    // Ouvrir la fiche du Sauce Labs Backpack.
    cy.get('[data-test="item-4-title-link"]').click();
    // Vérifier que la fiche du produit est affichée avant de revenir au catalogue.
    cy.get('[data-test="inventory-item-name"]').should('be.visible').and('have.text', 'Sauce Labs Backpack');

    // Cliquer sur le bouton de retour vers la liste des produits.
    cy.get('[data-test="back-to-products"]').click();

    // Vérifier que le navigateur est revenu à la page d'inventaire.
    cy.location('pathname').should('eq', '/inventory.html');
    // Vérifier que le titre Products est visible sur la page du catalogue.
    cy.get('[data-test="title"]').should('be.visible').and('have.text', 'Products');
    // Vérifier que les six produits sont de nouveau affichés.
    cy.get('.inventory_item').should('have.length', 6);
  });
});
